def eq(tex):
    return '<div class="equation math-tex" data-tex="'+html.escape(tex,quote=True)+'"></div>'


SLIDES = []
def slide(title, text, tex=None, question=None, answer=None, minutes=2):
    # Индексы переменных в обычном тексте; формулы data-tex добавляются ниже.
    body = re.sub(r'(?<![\w-])([pqxF])_(d|c|ext)(?![\w-])', r'<i>\1<sub>\2</sub></i>', text)
    if tex: body += ''.join(eq(t) for t in ([tex] if isinstance(tex,str) else tex))
    if question:
        body += '<aside class="discussion"><strong>Обсудим.</strong> '+question+'<details><summary>Показать разбор</summary><p>'+answer+'</p></details></aside>'
    SLIDES.append((title, body, minutes))


def playback(kind):
    return f'''<div class="lab" data-lab="{kind}"><div class="controls"><label>Регулятор <select class="method"><option value="computed-torque">Computed torque</option><option value="impedance">Impedance</option><option value="admittance">Admittance</option></select></label><button class="play">▶ / Ⅱ</button><label>Время <input class="scrub" type="range" min="0" max="9.98" step="any" value="0"><output class="clock">0,00 с</output></label></div><div class="split"><div class="stage"><canvas class="robot" aria-label="Анимация 2R по записанным данным MuJoCo"></canvas></div><div class="stage"><canvas class="plot" aria-label="Отклонение рабочего органа и внешняя сила"></canvas></div></div><p class="legend">Бордовый — фактическое p · синий — номинальное p_d · оранжевый — команда p_c</p><p class="status"></p></div>'''

slide('Управление 2R', '<p class="eyebrow">Моделирование робототехнических систем · лекция 4</p><h1>Движение.<br>Сила. Податливость.</h1><p class="lead">Линеаризация обратной связью, impedance и admittance на одном вертикальном роботе.</p><p>90 минут · выводы, виртуальные эксперименты, MuJoCo</p>',minutes=1)
slide('Маршрут занятия', '<div id="agenda"></div><p>В конце: объяснить, почему большая ошибка положения иногда означает правильное поведение.</p>')
slide('Задание → момент → движение', '<div class="pipeline">Траектория → регулятор → привод → робот → измерение ↺</div><p>Обратная динамика вычисляет момент для заданного ускорения. Обратная связь исправляет отклонение от задания.</p>',question='Достаточно ли идеальной заранее рассчитанной последовательности моментов?',answer='Только при точных модели и начальном состоянии и отсутствии возмущений. Обратная связь нужна для исправления реальных отклонений.')
slide('Вертикальный 2R: договоримся о знаках', '<p>Ось x вправо, z вверх. q₁ — от +x к +z, q₂ — относительно первого звена. Положение p отсчитываем от плеча.</p><div class="stage"><canvas id="geometry" aria-label="Вертикальный 2R и направления координат"></canvas></div><p>Два звена по 0,4 м и 2 кг; g=9,81 м/с² вниз. Мировая высота плеча — 0,3 м.</p>')
slide('Положение и скорость', '<p>Для управления в декартовом пространстве сначала нужен кинематический интерфейс.</p>',[r'p=\begin{bmatrix}\ell_1\cos q_1+\ell_2\cos(q_1+q_2)\\\ell_1\sin q_1+\ell_2\sin(q_1+q_2)\end{bmatrix}',r'\dot p=J(q)\dot q,\qquad\ddot p=J\ddot q+\dot J\dot q'])
slide('Дифференцируем задание', '<p>Выбираем одну ветвь обратной кинематики. Скорость и ускорение должны соответствовать той же траектории.</p>',[r'q_d=\operatorname{IK}(p_d)',r'J(q_d)\dot q_d=\dot p_d',r'J(q_d)\ddot q_d=\ddot p_d-\dot J(q_d,\dot q_d)\dot q_d'],question='На каком состоянии вычислять J для производных эталона?',answer='На эталонных q_d и q̇_d. Для фактической скорости рабочего органа — на текущем состоянии робота.')
slide('Сингулярность не исчезает в регуляторе', '<p>На границе рабочей области одна декартова скорость требует очень больших суставных скоростей. Достижимость позиции ещё не гарантирует хорошую обусловленность.</p>',r'\det J=\ell_1\ell_2\sin q_2',question='Почему используем solve(J,v), а не inv(J) @ v?',answer='Решение линейной системы не требует явно строить обратную матрицу. При этом solve тоже не устраняет физическую сингулярность.')
slide('Объект управления', '<p>F_ext — сила среды <strong>на робот</strong>. Гравитация включена. c — вектор, B — суставное вязкое трение.</p>',r'M(q)\ddot q+c(q,\dot q)+G(q)+B\dot q=\tau+J^TF_{\rm ext}')
slide('Что скрыто в M, c и G', '<p>Инерции звеньев относительно центров масс включены: Iᵢ=mᵢℓᵢ²/12. Эти же параметры заданы в XML.</p>',[r'M=\begin{bmatrix}a+2\beta\cos q_2&d+\beta\cos q_2\\d+\beta\cos q_2&d\end{bmatrix}',r'\begin{gathered}\beta=m_2\ell_1r_2,\quad d=I_2+m_2r_2^2,\\a=I_1+I_2+m_1r_1^2+m_2(\ell_1^2+r_2^2).\end{gathered}'])
slide('PD плюс компенсация тяжести', '<p>Компенсация G помогает удерживать позу. При движении инерционные и кориолисовы моменты всё ещё создаются за счёт ошибки.</p>',r'\tau=K_p^\tau(q_d-q)+K_d^\tau(\dot q_d-\dot q)+G(q)',question='Линеаризует ли такой закон всю динамику 2R?',answer='Нет. Конфигурационно зависимая M и связь суставов остаются в замкнутом уравнении.')
slide('Шаг 1: выбираем желаемое ускорение', '<p>Пусть e=q_d−q. Сформируем виртуальное ускорение, которое заранее содержит ускорение задания.</p>',r'v=\ddot q_d+K_d\dot e+K_pe')
slide('Шаг 2: реализуем его моментом', '<p>Используем текущие q,q̇ для модели и производные задания для feedforward. Это computed torque.</p>',r'\boxed{\tau=M(q)v+c(q,\dot q)+G(q)+B\dot q}',question='Зачем нужна обратная связь, если есть обратная динамика?',answer='Слагаемые K_dė и K_pe возвращают систему к траектории после отклонения; одно только q̈_d этого не делает.')
slide('Шаг 3: подстановка в динамику', '<p>Точная модель, нет внешней силы, ограничения момента неактивны:</p>',[r'M\ddot q+c+G+B\dot q=Mv+c+G+B\dot q',r'\ddot q=v\quad\Longrightarrow\quad\boxed{\ddot e+K_d\dot e+K_pe=0}'],minutes=3)
slide('Что означает feedback linearization', '<p>Нелинейный закон управления создаёт линейную динамику ошибки. Физическая механика остаётся нелинейной.</p><p>M(q) обратима для полностью приводного робота. Инверсия J нужна только при декартовом формировании задания.</p>',r'\ddot q=f(q,\dot q)+M^{-1}(q)\tau')
slide('Полюса и настройка', '<p>Для диагональных коэффициентов выбираем частоту и демпфирование каждой ошибки. В примере внутренний контур: ω=35 рад/с, ζ=1.</p>',[r'K_{p,i}=\omega_i^2,\quad K_{d,i}=2\zeta_i\omega_i',r'\ddot e_i+2\zeta_i\omega_i\dot e_i+\omega_i^2e_i=0'],question='Почему 1225 с⁻² — не жёсткость декартовой пружины?',answer='Этот коэффициент превращает угловую ошибку в ускорение. Декартова жёсткость имеет размерность Н/м.')
slide('Лаборатория ошибки', '<p>Идеальная замкнутая модель ë+2ζωė+ω²e=0. Начальная ошибка 0,1 рад; скорость нулевая. Это аналитическая модель, <strong>не MuJoCo</strong>.</p><div class="controls"><label>ω <input id="omega" type="range" min="1" max="16" value="5" step=".25"><output></output></label><label>ζ <input id="zeta" type="range" min=".05" max="2" value="1" step=".05"><output></output></label></div><div class="stage"><canvas id="error-lab" aria-label="Динамика ошибки при изменении частоты и демпфирования"></canvas></div>',question='Какая настройка даёт колебания? А самая быстрая всегда лучшая?',answer='ζ<1 даёт колебательность. Большая ω требует больших ускорений, моментов и частоты обновления.',minutes=3)
slide('Когда идеальный вывод перестаёт работать', '<p>Неточная масса, неизвестная нагрузка, трение, шум скорости, задержки и насыщение момента меняют динамику ошибки.</p>',r'\ddot e+K_d\dot e+K_pe=-M^{-1}r',question='Возмущение +JᵀF_ext с каким знаком входит сюда?',answer='С минусом: e=q_d−q. Та же сила ускоряет робот в положительном направлении и уменьшает соответствующую ошибку.',minutes=3)
slide('Насыщение — часть физики', '<p>В примере приводы ограничены ±35 Н·м. В CSV записывается фактически ограниченный момент и доля насыщенных шагов.</p>',r'\tau_{\rm applied}=\operatorname{clip}(\tau_{\rm command},-35,35)',question='Можно ли из устойчивости непрерывного закона заключить устойчивость при любом шаге?',answer='Нет. Цифровой регулятор, удержание команды и численный интегратор создают дискретную систему.')
slide('От точности к взаимодействию', '<p>При сборке, контакте и взаимодействии с человеком полезно управлять отношением силы и движения.</p><p>Жёсткое удержание номинального положения может противоречить задаче уступить внешней силе.</p>')
slide('Якобиан переносит мощность', '<p>Сила среды на рабочем органе преобразуется в обобщённые моменты.</p>',[r'\tau_{\rm ext}=J^TF_{\rm ext}',r'\dot q^T\tau_{\rm ext}=\dot p^TF_{\rm ext}'],question='Нужно ли для преобразования силы вычислять J⁻¹?',answer='Нет. Преобразование силы — Jᵀ, оно следует из равенства мощностей.')
slide('Impedance: движение → сила', '<p>Виртуальная пружина реагирует на отклонение, демпфер — на относительную скорость. Выход регулятора — момент.</p>',[r'F_c=K_x(p_d-p)+D_x(\dot p_d-\dot p)',r'\boxed{\tau=G+J^TF_c}'])
slide('Проверяем статический знак', '<p>При постоянной внешней силе, неподвижном равновесии и невырожденном J:</p>',[r'0=J^T[K_x(p_d-p)+F_{\rm ext}]',r'p-p_d=K_x^{-1}F_{\rm ext}'],question='Сила вправо: куда сместится рабочий орган?',answer='Вправо. Для 4 Н и 120 Н/м статическое смещение 33,3 мм. В коротком импульсе пик может отличаться.')
slide('Виртуальная пружина: интерактивно', '<p>Статическое равновесие без инерционного перехода. Здесь меняем K и F, а не запускаем динамику MuJoCo.</p><div class="controls"><label>K, Н/м <input id="spring-k" type="range" min="40" max="240" step="10" value="120"><output></output></label><label>Fₓ, Н <input id="spring-f" type="range" min="-4" max="4" step=".25" value="4"><output></output></label></div><div class="stage"><canvas id="spring-lab" aria-label="Статическое смещение от силы и жёсткости"></canvas></div><p id="spring-status"></p>',minutes=3)
slide('Энергия объясняет податливость', '<p>Для неподвижной цели и точной компенсации G энергия состоит из кинетической и энергии виртуальной пружины.</p>',[r'H=\tfrac12\dot q^TM\dot q+\tfrac12(p-p_d)^TK_x(p-p_d)',r'\dot H=F_{\rm ext}^T\dot p-\dot p^TD_x\dot p-\dot q^TB\dot q'],question='Что изменится при движущемся p_d?',answer='Задание становится дополнительным источником энергии. Формула для неподвижной цели уже неполна.',minutes=3)
slide('Какую инерцию ощущает среда?', '<p>В нашем impedance-примере мы задаём жёсткость и демпфирование. Эффективная масса остаётся физической и зависит от позы.</p>',r'\Lambda(q)=(JM^{-1}J^T)^{-1}',question='Можно ли назвать параметр 1,5 кг массой этого impedance-регулятора?',answer='Нет. 1,5 кг — виртуальная масса отдельного admittance-фильтра. В impedance-примере произвольная инерция не формируется.')
slide('Admittance: сила → движение', '<p>Измеренная сила двигает виртуальную массу. Полученное смещение изменяет цель внутреннего позиционного контура.</p>',[r'\boxed{M_a\ddot\delta+D_a\dot\delta+K_a\delta=F_{\rm ext}}',r'p_c=p_d+\delta'])
slide('Два контура, два состояния', '<div class="pipeline">F_ext → виртуальная динамика δ → p_c → IK → computed torque → робот</div><p>Внешний контур хранит δ,δ̇. Внутренний использует q,q̇. Фактическое p может отличаться и от p_d, и от p_c.</p>',r'\begin{aligned}\dot p_c&=\dot p_d+\dot\delta,\\\ddot p_c&=\ddot p_d+\ddot\delta.\end{aligned}')
slide('Как выбирать Mₐ, Dₐ, Kₐ', '<p>Номинально Mₐ=1,5 кг, Dₐ=22 Н·с/м, Kₐ=120 Н/м на каждой оси. Это ω≈8,94 рад/с, ζ≈0,82.</p>',[r'\omega_a=\sqrt{K_a/M_a},\qquad\zeta_a=\frac{D_a}{2\sqrt{M_aK_a}}',r'\delta_{\rm eq}=F/K_a'],question='Массу уменьшили в 4 раза, остальные коэффициенты те же. Что меняется?',answer='Собственная частота удваивается, относительное демпфирование тоже удваивается. Статическое смещение не меняется.')
slide('Лаборатория виртуального фильтра', '<p>Известный толчок 4 Н между 3–5 с; RK4 с шагом 2 мс. Это только внешний фильтр, без динамики робота.</p><div class="controls"><label>Mₐ, кг <input id="adm-m" type="range" min=".3" max="5" step=".1" value="1.5"><output></output></label><label>Dₐ, Н·с/м <input id="adm-d" type="range" min="2" max="50" step="1" value="22"><output></output></label><label>Kₐ, Н/м <input id="adm-k" type="range" min="40" max="240" step="10" value="120"><output></output></label></div><div class="stage"><canvas id="admittance-lab" aria-label="Смещение виртуального фильтра при силовом импульсе"></canvas></div><p id="adm-status"></p>',minutes=3)
slide('Внутренний контур не идеален', '<p>Сила физически действует на робот и одновременно измеряется внешним фильтром. В коде она не вычитается из момента для идеального подавления.</p>',r'\ddot e_q+K_d\dot e_q+K_pe_q=-M^{-1}J^TF_{\rm ext}',question='Совпадёт ли фактическое p с p_c совершенно точно?',answer='Нет. Остаточная ошибка зависит от полосы внутреннего контура, внешней силы и дискретизации. Поэтому в данных показаны обе траектории.')
slide('Три архитектуры рядом', '<table><tr><th>Метод</th><th>Выход</th><th>Цель</th></tr><tr><td>Computed torque</td><td>Момент</td><td>Заданная динамика ошибки</td></tr><tr><td>Impedance</td><td>Момент виртуальной пружины</td><td>Податливое взаимодействие</td></tr><tr><td>Admittance</td><td>Новое задание движения</td><td>Податливость через внутренний сервоконтур</td></tr></table><p>Внутри admittance здесь тоже используется computed torque. Это композиция методов.</p>')
slide('MuJoCo: что именно моделируется', '<p>Вертикальный 2R, реальные инерции XML, трение, гравитация, насыщение. Интегратор робота — implicitfast, шаг 2 мс.</p><p>Контакты отключены. Известный толчок прикладывается к tip через mj_applyFT. Он же служит идеальным измерением для admittance.</p><p>Датчик силы, шум и столкновение со стенкой в этом опыте не моделируются.</p>')
slide('Эксперимент A: следование восьмёрке', '<p>Записанные данные настоящего запуска MuJoCo. Выберите регулятор, запустите анимацию или переместите время.</p>'+playback('tracking'),minutes=3)
slide('Как читать сравнение слежения', '<p>Без внешней силы δ=0, поэтому admittance совпадает с computed torque. Виртуальная пружина сохраняет физическую динамику и даёт большую ошибку на движущейся цели.</p><div id="tracking-metrics"></div><p class="small">Шаг 2 мс, 10 с. Числа зависят от модели и дискретизации; это не характеристика реального оборудования.</p>')
slide('Эксперимент B: один толчок для всех', '<p>Цель неподвижна. Fₓ=4sin²(π(t−3)/2) Н для 3&lt;t&lt;5 с; Fz=0. Сравните номинальную цель, команду и фактическое движение.</p>'+playback('interaction'),minutes=3)
slide('Почему большая ошибка бывает правильной', '<p>Computed torque сопротивляется отклонению. Impedance уступает силе через физическую динамику. Admittance перемещает само задание.</p><p>Сравниваем отдельно отклонение от p_d и ошибку слежения за p_c.</p><div id="interaction-metrics"></div>',question='Какой метод победит по минимальной ошибке относительно p_d? Достаточно ли этого критерия?',answer='Жёсткий внутренний контур обычно уменьшает отклонение. Но для задачи уступить силе такая метрика не отражает желаемую податливость.')
slide('Изменяем один параметр', '<p>Работа в парах (из папки control_2r): уменьшите жёсткость 120→60 Н/м. Сначала предскажите статический эффект, затем запустите опыт.</p><pre>python simulate.py --method impedance \\<br>  --task interaction --force \\<br>  --stiffness 60 --out /tmp/2r-soft</pre>',question='Должен ли пик короткого толчка увеличиться ровно вдвое?',answer='Нет. Вдвое увеличивается статическая податливость. Переход зависит от инерции, демпфирования и длительности силы.',minutes=3)
slide('Что делает один шаг программы', '<ol><li>mj_forward: согласовать кинематику со state.</li><li>Считать q,q̇ и силу; вычислить команду.</li><li>Ограничить моменты, обнулить qfrc_applied.</li><li>mj_applyFT: приложить силу в мировой системе.</li><li>Записать данные, обновить admittance-фильтр.</li><li>mj_step: продвинуть физическую динамику.</li></ol>')
slide('Два солвера нельзя смешивать', '<p>MuJoCo интегрирует состояние робота. Наш RK4 интегрирует виртуальное состояние admittance. Частота управления — также 500 Гц.</p><p>Повторите computed torque с шагами 4, 2 и 1 мс. Сравните RMS и максимум момента, сохранив коэффициенты.</p>',question='Почему порядок RK4 фильтра не делает всю систему четвёртого порядка?',answer='Есть другой интегратор робота и удержание команды между отсчётами. Порядок отдельного блока не переносится автоматически на связанный алгоритм.')
slide('Проверяем уравнения, а не только картинку', '<p>verify.py сравнивает M и bias с MuJoCo, проверяет J̇ и производные задания конечными разностями, тождество computed torque и баланс мощности.</p><p>Отдельные прогоны проверяют конечность состояния, отсутствие насыщения и возврат после толчка.</p><pre>python control_2r/verify.py</pre>')
slide('Разбор типичных ошибок', '<ul><li>Забыть G в вертикальном роботе.</li><li>Вычислять M на q_d вместо текущего q.</li><li>Перепутать JᵀF и J⁻¹v.</li><li>Назвать пружину с демпфером точным формированием M_d.</li><li>Не различать p_d, p_c и фактическое p.</li><li>Принять известную приложенную силу за модель датчика.</li></ul>')
slide('Проверим понимание', '<p>1. Выведите динамику ошибки при внешней силе.</p><p>2. Объясните физические единицы Kp, Kx и Ma.</p><p>3. Выберите интерфейс для готового позиционного сервопривода.</p><p>4. Объясните, почему слишком маленькая виртуальная масса усложняет реализацию.</p>',question='Ключи к ответам',answer='1: −M⁻¹JᵀF. 2: с⁻², Н/м, кг. 3: внешний admittance часто удобен. 4: растут частота виртуальной динамики и требования к полосе/дискретизации.',minutes=3)
slide('Modern Robotics: куда читать дальше', '<div class="references"><p>Kevin M. Lynch, Frank C. Park. <i>Modern Robotics: Mechanics, Planning, and Control.</i></p><p><a href="https://modernrobotics.northwestern.edu/nu-gm-book-resource/11-4-motion-control-with-torque-or-force-inputs-part-3-of-3/">§11.4, часть 3 — computed torque</a></p><p><a href="https://modernrobotics.northwestern.edu/nu-gm-book-resource/8-3-newton-euler-inverse-dynamics/">§8.3 — обратная динамика</a> · <a href="https://modernrobotics.northwestern.edu/nu-gm-book-resource/8-5-forward-dynamics-of-open-chains/">§8.5 — прямая динамика</a></p><p><a href="https://modernrobotics.northwestern.edu/">Глава 5 — якобианы; §11.5–11.6 — управление силой и гибридное управление</a></p><p class="small">Гибридное управление не тождественно impedance/admittance. Виртуальная пружина также опирается на §3.3 исходной лекции.</p></div>')
slide('MuJoCo и материалы занятия', '<p><a href="https://mujoco.readthedocs.io/en/stable/computation/">MuJoCo: динамика и интеграторы</a></p><p><a href="https://mujoco.readthedocs.io/en/stable/APIreference/APIfunctions.html#mj-applyft">mj_applyFT: сила в точке тела</a> · <a href="https://mujoco.readthedocs.io/en/stable/python.html#passive-viewer">Passive viewer</a></p><p><a href="../lecture_notes.md">Конспект</a> · <a href="../control_2r/README.md">Примеры и команды</a> · <a href="../../../SRS/lecture_3/lecture_3.pdf">Исходный PDF</a></p><p>Домашнее задание: изменить массу только в XML и оценить чувствительность computed torque к ошибке модели.</p>',minutes=1)

CSS = '''
:root{--wine:#7b263d;--orange:#b65b20;--blue:#477994;--pale:#eaf3fa;--line:#c4d9e8}*{box-sizing:border-box}html,body{margin:0;height:100%;overflow:hidden}body{background:white;color:#171717;font:26px/1.4 "CMU Serif",serif;display:grid;grid-template-rows:64px 1fr 60px}header,footer{padding:12px 4vw;display:flex;align-items:center;gap:18px;border-bottom:1px solid var(--line)}footer{border-top:1px solid var(--line);border-bottom:0}header strong{color:var(--wine)}header small{margin-left:auto;font-size:18px}main{min-height:0}.slide{display:none;height:100%;overflow:auto;padding:24px 6vw 40px}.slide.active{display:block}h1{font-size:clamp(52px,5vw,82px);line-height:1.08;margin:18px 0;color:var(--wine)}h2{font-size:42px;font-weight:400;line-height:1.12;margin:0 0 24px;color:var(--wine)}p{margin:14px 0}a{color:var(--wine);text-decoration-thickness:1px;text-underline-offset:4px}.eyebrow,.small{font-size:21px;color:#454545}.lead{font-size:32px}.equation{font-size:29px;background:#f5f9fc;border-left:3px solid var(--blue);padding:12px 16px;margin:16px 0;overflow-x:auto}.katex{font-size:1.08em}.discussion{margin-top:24px;padding-top:18px;border-top:1px solid var(--line)}.discussion strong,summary{color:var(--orange)}details{padding:10px 16px;background:var(--pale);margin-top:12px}summary{cursor:pointer}button,select,input{font:22px "CMU Serif",serif}button,select{background:white;color:var(--wine);border:1px solid var(--line);border-radius:4px;padding:7px 12px;cursor:pointer}button:hover,button:focus-visible{background:var(--pale)}input[type=range]{width:160px;accent-color:var(--wine)}.controls{display:flex;align-items:center;flex-wrap:wrap;gap:18px;padding:12px;background:var(--pale)}label{display:flex;align-items:center;gap:10px;font-size:22px}.split{display:grid;grid-template-columns:1fr 1fr;gap:20px}.stage{position:relative;border:1px solid var(--line);background:#fff;margin:14px 0}.stage canvas{display:block;width:100%;height:280px}#geometry{height:320px}#error-lab,#admittance-lab{height:300px}canvas{touch-action:pan-y}.zoom{position:absolute;top:5px;right:5px;font-size:16px}.legend{font-size:19px;color:var(--blue)}.status{font-size:21px}.pipeline{padding:24px;background:var(--pale);color:var(--wine);font-size:29px}table{border-collapse:collapse;width:100%;font-size:24px}th{text-align:left;color:var(--wine)}td,th{padding:10px;border-bottom:1px solid var(--line)}pre,code{font-family:"CMU Typewriter",monospace}pre{padding:20px;background:#f5f9fc;font-size:22px;overflow:auto}.progress{height:3px;flex:1;background:var(--pale)}.progress i{display:block;background:var(--wine);height:100%}#counter,#time-label{font-size:18px;white-space:nowrap}#time-label{color:var(--orange)}dialog{border:1px solid var(--line);width:90vw;max-width:1500px;max-height:90vh;overflow:auto;background:white;padding:24px}dialog::backdrop{background:#ffffffed}#overview .items{display:grid;grid-template-columns:1fr 1fr;gap:8px}#overview button{text-align:left;font-size:20px}#figure-modal img{width:100%;max-height:75vh;object-fit:contain}.tex-error{border:2px solid red}.hint{font-size:16px}li{margin:12px 0}
@media(max-width:950px){body{font-size:24px}header small,.hint,#time-label{display:none}.slide{padding:24px}.split{grid-template-columns:1fr}h2{font-size:36px}.equation{font-size:26px}#overview .items{grid-template-columns:1fr}table{font-size:20px}.stage canvas{height:250px}}
@media(max-height:800px) and (min-width:951px){body{font-size:24px}.slide{padding-top:18px}h2{font-size:38px;margin-bottom:18px}.equation{font-size:27px;padding:10px 14px}.stage canvas{height:230px}#geometry{height:260px}#error-lab,#admittance-lab{height:250px}}
@media print{html,body{height:auto;overflow:visible;display:block}header,footer,dialog,.zoom{display:none!important}.slide{display:block;height:auto;overflow:visible;break-after:page}.slide details>p{display:block}.slide{font-size:18px}.equation{font-size:22px}h2{font-size:30px}}
'''

JS = r'''
const slides=[...document.querySelectorAll('.slide')];let active=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function go(index){active=Math.max(0,Math.min(slides.length-1,index));slides.forEach((s,i)=>s.classList.toggle('active',i===active));slides[active].scrollTop=0;document.getElementById('counter').textContent=`${active+1} / ${slides.length}`;document.getElementById('progress').style.width=`${(active+1)/slides.length*100}%`;let start=slides.slice(0,active).reduce((s,x)=>s+Number(x.dataset.minutes),0);document.getElementById('time-label').textContent=`План: ${start}–${start+Number(slides[active].dataset.minutes)} мин`;history.replaceState(null,'',`#${active+1}`);draw();}
function menu(){document.getElementById('overview').showModal();}
document.getElementById('previous').onclick=()=>go(active-1);document.getElementById('next').onclick=()=>go(active+1);document.getElementById('menu').onclick=menu;
document.getElementById('fullscreen').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen().catch(()=>{});
const overview=document.getElementById('overview');slides.forEach((s,i)=>{const b=document.createElement('button');b.textContent=`${i+1}. ${s.dataset.title}`;b.onclick=()=>{overview.close();go(i);document.getElementById('menu').focus()};overview.querySelector('.items').append(b)});
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||document.querySelector('dialog[open]'))return;if(['ArrowRight','PageDown','ArrowLeft','PageUp','Home','End','Space'].includes(e.code))e.preventDefault();if(['ArrowRight','PageDown'].includes(e.code))go(active+1);if(['ArrowLeft','PageUp'].includes(e.code))go(active-1);if(e.code==='Home')go(0);if(e.code==='End')go(slides.length-1);if(e.code==='KeyO')menu();if(e.code==='KeyF')document.getElementById('fullscreen').click();if(e.code==='Space'){const lab=slides[active].querySelector('.lab');if(lab)lab.querySelector('.play').click()}});
const colors=['#7b263d','#477994','#b65b20'];
function canvas(id){const el=typeof id==='string'?document.getElementById(id):id;let w=el.clientWidth,h=el.clientHeight;const ratio=devicePixelRatio||1;el.width=Math.round(w*ratio);el.height=Math.round(h*ratio);let c=el.getContext('2d');c.scale(ratio,ratio);c.clearRect(0,0,w,h);c.fillStyle='#fff';c.fillRect(0,0,w,h);c.font='18px "CMU Serif"';return {c,w,h};}
function line(c,points,color,width=2){c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.strokeStyle=color;c.lineWidth=width;c.stroke();}
function chart(el,series,xmax,ymin,ymax,ylabel,cursor=null){let {c,w,h}=canvas(el);let X=x=>54+x/xmax*(w-76),Y=y=>h-40-(y-ymin)/(ymax-ymin)*(h-70);c.fillStyle='#222';for(let i=0;i<=4;i++){let y=ymin+i*(ymax-ymin)/4;line(c,[[54,Y(y)],[w-22,Y(y)]],'#e0e8ef',1);c.fillText(y.toFixed(1),3,Y(y)+5)}for(let i=0;i<=5;i++){let x=xmax*i/5;c.fillText(x.toFixed(0),X(x)-5,h-14)}c.fillText(ylabel,54,21);c.fillText('t, с',w-49,21);series.forEach(s=>line(c,s.data.map(p=>[X(p[0]),Y(p[1])]),s.color));if(cursor!==null)line(c,[[X(cursor),30],[X(cursor),h-40]],'#b65b20',1);}
function fk(q){return [.4*Math.cos(q[0])+.4*Math.cos(q[0]+q[1]),.4*Math.sin(q[0])+.4*Math.sin(q[0]+q[1])]}
function robot(el,q,pd,pc,force=[0,0],trail=[]){let {c,w,h}=canvas(el),scale=Math.min((w-80)/.85,(h-60)/.9);let X=x=>50+x*scale,Y=z=>h-30-(z+.25)*scale;let p1=[.4*Math.cos(q[0]),.4*Math.sin(q[0])],p=fk(q);line(c,[[X(0),Y(0)],[X(.75),Y(0)]],'#999',1);line(c,[[X(0),Y(-.02)],[X(0),Y(.6)]],'#999',1);c.fillStyle='#222';c.fillText('x →',X(.65),Y(0)+24);c.fillText('z ↑',X(0)-32,30);c.fillText('g ↓',w-65,48);if(trail.length)line(c,trail.map(a=>[X(a[0]),Y(a[1])]),'#c4d9e8',2);line(c,[[X(0),Y(0)],[X(p1[0]),Y(p1[1])]],colors[1],8);line(c,[[X(p1[0]),Y(p1[1])],[X(p[0]),Y(p[1])]],colors[0],8);[[0,0],p1,p].forEach(v=>{c.beginPath();c.arc(X(v[0]),Y(v[1]),6,0,2*Math.PI);c.fillStyle='#222';c.fill()});[pd,pc].forEach((v,i)=>{c.strokeStyle=colors[i+1];c.lineWidth=2;c.strokeRect(X(v[0])-7-i*3,Y(v[1])-7-i*3,14+i*6,14+i*6)});if(Math.abs(force[0])>.01){let x=X(p[0]),y=Y(p[1]),dx=force[0]*14;line(c,[[x,y],[x+dx,y]],colors[2],3);line(c,[[x+dx-Math.sign(dx)*9,y-5],[x+dx,y],[x+dx-Math.sign(dx)*9,y+5]],colors[2],2);c.fillStyle=colors[2];c.fillText('F',x+dx,y-12)}}
function pulse(t){return t>3&&t<5?4*Math.sin(Math.PI*(t-3)/2)**2:0}
function rk4(y,t,h,f){let a=f(t,y),b=f(t+h/2,y.map((v,i)=>v+h*a[i]/2)),d=f(t+h/2,y.map((v,i)=>v+h*b[i]/2)),e=f(t+h,y.map((v,i)=>v+h*d[i]));return y.map((v,i)=>v+h*(a[i]+2*b[i]+2*d[i]+e[i])/6)}
let filterCache=null;
function filterData(){let m=+document.getElementById('adm-m').value,d=+document.getElementById('adm-d').value,k=+document.getElementById('adm-k').value,key=[m,d,k].join();if(filterCache&&filterCache.key===key)return filterCache;let y=[0,0],data=[];for(let i=0;i<=5000;i++){let t=i*.002;if(i%10===0)data.push([t,1000*y[0]]);y=rk4(y,t,.002,(t,s)=>[s[1],(pulse(t)-d*s[1]-k*s[0])/m])}return filterCache={key,data,m,d,k};}
function draw(){const page=slides[active];if(page.querySelector('#geometry'))robot('geometry',[-.5,1.8],[.4,.2],[.4,.2]);if(page.querySelector('#error-lab')){let omega=+document.getElementById('omega').value,zeta=+document.getElementById('zeta').value,y=[.1,0],data=[];for(let i=0;i<=3000;i++){let t=i*.002;if(i%5===0)data.push([t,y[0]]);y=rk4(y,t,.002,(_,s)=>[s[1],-2*zeta*omega*s[1]-omega**2*s[0]])}chart('error-lab',[{data,color:colors[0]}],6,-.1,.12,'e, рад');}
if(page.querySelector('#spring-lab')){let k=+document.getElementById('spring-k').value,f=+document.getElementById('spring-f').value;let pc=[.4+f/k,.2],c2=(pc[0]**2+pc[1]**2-.32)/.32,q2=Math.acos(c2),q1=Math.atan2(pc[1],pc[0])-Math.atan2(.4*Math.sin(q2),.4+.4*Math.cos(q2));robot('spring-lab',[q1,q2],[.4,.2],pc,[f,0]);document.getElementById('spring-status').textContent=`Δx = ${(1000*f/k).toFixed(1)} мм. Статическое равновесие, не переходный процесс.`;}
if(page.querySelector('#admittance-lab')){let a=filterData(),min=Math.min(-2,...a.data.map(v=>v[1])),max=Math.max(40,...a.data.map(v=>v[1]));chart('admittance-lab',[{data:a.data,color:colors[0]}],10,min,max,'δx, мм');document.getElementById('adm-status').textContent=`ω = ${Math.sqrt(a.k/a.m).toFixed(2)} рад/с; ζ = ${(a.d/(2*Math.sqrt(a.k*a.m))).toFixed(2)}; статическое смещение при 4 Н = ${(4000/a.k).toFixed(1)} мм.`;}
page.querySelectorAll('.lab').forEach(drawPlayback);}
const records=JSON.parse(document.getElementById('recorded-data').textContent);
function drawPlayback(lab){let type=lab.dataset.lab,method=lab.querySelector('.method').value,rows=records[type][method].rows,t=+lab.querySelector('.scrub').value,index=Math.min(rows.length-1,Math.floor(t/.02)),r=rows[index];robot(lab.querySelector('.robot'),r.slice(1,3),r.slice(7,9),r.slice(9,11),r.slice(11,13),rows.slice(0,index+1).map(a=>a.slice(5,7)));let data=rows.map(a=>[a[0],1000*(a[5]-a[7])]),command=rows.map(a=>[a[0],1000*(a[9]-a[7])]),min=Math.min(-2,...data.map(a=>a[1])),max=Math.max(2,...data.map(a=>a[1]));chart(lab.querySelector('.plot'),[{data,color:colors[0]},{data:command,color:colors[2]}],10,min,max,'Отклонение x, мм',t);lab.querySelector('.clock').textContent=t.toFixed(2)+' с';lab.querySelector('.status').textContent=`Fx = ${r[11].toFixed(2)} Н; τ₁ = ${r[13].toFixed(2)} Н·м; Ошибка к команде = ${(1000*Math.hypot(r[5]-r[9],r[6]-r[10])).toFixed(2)} мм; насыщение ${r[15]?'да':'нет'}.`;}
document.querySelectorAll('.lab').forEach(lab=>{lab.dataset.playing=reduced?'false':'true';lab.querySelector('.play').onclick=()=>lab.dataset.playing=lab.dataset.playing==='true'?'false':'true';lab.querySelector('.scrub').oninput=()=>{lab.dataset.playing='false';draw()};lab.querySelector('.method').onchange=draw;});
document.querySelectorAll('input[type=range]:not(.scrub)').forEach(input=>{const update=()=>{const out=input.parentElement.querySelector('output');if(out)out.textContent=input.value;draw()};input.addEventListener('input',update);input.parentElement.querySelector('output').textContent=input.value;});
let last=0;function frame(now){let dt=last?Math.min(.05,(now-last)/1000):0;last=now;slides[active].querySelectorAll('.lab').forEach(lab=>{if(lab.dataset.playing==='true'){const slider=lab.querySelector('.scrub');slider.value=(+slider.value+dt)%9.98;drawPlayback(lab)}});requestAnimationFrame(frame)}
document.querySelectorAll('.stage canvas').forEach(el=>{let button=document.createElement('button');button.className='zoom';button.textContent='Увеличить ⤢';button.onclick=()=>{const modal=document.getElementById('figure-modal');modal.querySelector('img').src=el.toDataURL();modal.querySelector('img').alt=el.getAttribute('aria-label');modal.showModal()};el.parentElement.append(button)});
function metricTable(kind){let markup='<table><tr><th>Метод</th><th>RMS к p_d, мм</th><th>RMS к p_c, мм</th><th>Насыщение</th></tr>';for(const [method,item] of Object.entries(records[kind])){let a=item.metrics;markup+=`<tr><td>${method}</td><td>${a.rms_nominal_mm.toFixed(3)}</td><td>${a.rms_command_mm.toFixed(3)}</td><td>${a.saturation_percent.toFixed(1)}%</td></tr>`}return markup+'</table>'}['tracking','interaction'].forEach(k=>document.getElementById(k+'-metrics').innerHTML=metricTable(k));
let total=0;document.getElementById('agenda').innerHTML='<table>'+[[0,7,'Объект и кинематика'],[7,18,'Линеаризация обратной связью'],[18,25,'Импеданс'],[25,31,'Адмиттанс'],[31,40,'Эксперименты и проверка'],[40,slides.length,'Обсуждение и источники']].map(([a,b,title])=>{let minutes=slides.slice(a,b).reduce((s,x)=>s+Number(x.dataset.minutes),0),start=total;total+=minutes;return `<tr><td>${start}–${total} мин</td><td>${title}</td></tr>`}).join('')+'</table>';
window.deck={go,filterData,records,rk4};window.__modelTestsPassed=Math.abs(filterData().data.at(-1)[1])<.01&&slides.reduce((s,x)=>s+Number(x.dataset.minutes),0)===90;
go(Number(location.hash.slice(1)||1)-1);document.fonts.ready.then(()=>{document.documentElement.dataset.fontsReady='true';draw()});window.addEventListener('resize',draw);requestAnimationFrame(frame);
'''


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--record',action='store_true')
    args=parser.parse_args()
    destination=ROOT/'presentation'
    destination.mkdir(exist_ok=True)
    record_path=destination/'recordings.json'
    if args.record:
        from control_2r.simulate import run,summarize,METHODS
        data={}
        for task in ('tracking','interaction'):
            data[task]={}
            for method in METHODS:
                rows=run(method,task=task,force=task=='interaction')
                data[task][method]={'metrics':summarize(rows),'rows':rows[::10].round(8).tolist()}
        record_path.write_text(json.dumps(data,separators=(',',':')))
    recorded=record_path.read_text()
    # 43 слайда: базовые 2 мин, практикумы 3 мин; нормируем до 90 мин.
    minutes=[s[2] for s in SLIDES]
    while sum(minutes)>90:
        index=next(i for i in range(len(minutes)-2,0,-1) if minutes[i]>2)
        minutes[index]-=1
    while sum(minutes)<90:
        index=next(i for i in range(2,len(minutes)-2) if minutes[i]==2)
        minutes[index]+=1
    sections=''.join(f'<section class="slide" data-title="{html.escape(title,quote=True)}" data-minutes="{minutes[i]}" aria-label="{i+1}. {html.escape(title,quote=True)}"><h2>{html.escape(title)}</h2>{body}</section>' for i,(title,body,_) in enumerate(SLIDES))
    runtime=(ROOT.parent/'presentation_assets/katex-0.16.22/dist/katex.min.js').read_text()
    content=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Лекция 4 · Управление 2R</title><style>{font_css()}\n{CSS}</style></head><body><header><strong>Управление 2R</strong><small>Моделирование робототехнических систем · 90 минут</small><button id="menu">Обзор O</button><button id="fullscreen">Экран F</button></header><main>{sections}</main><footer><button id="previous" aria-label="Предыдущий слайд">←</button><span id="counter"></span><div class="progress"><i id="progress"></i></div><span id="time-label"></span><span class="hint">← → · O обзор · F экран · пробел пауза</span><button id="next" aria-label="Следующий слайд">→</button></footer><dialog id="overview"><button class="close">Закрыть</button><h2>Содержание</h2><div class="items"></div></dialog><dialog id="figure-modal"><button class="close">Закрыть</button><img alt=""></dialog><script id="recorded-data" type="application/json">{recorded}</script><script id="katex-runtime">{runtime}</script><script>{MATH_TOOLS.replace('typesetAll();','typesetAll();')}</script><script id="deck-code">{JS}</script></body></html>'''
    (destination/'index.html').write_text(content)
    plan=['# План презентации: 90 минут','', '| Время | Слайд |', '|---|---|']
    start=0
    for (title,_,_),duration in zip(SLIDES,minutes):
        plan.append(f'| {start}–{start+duration} | {title} |');start+=duration
    (destination/'TEACHING_PLAN.md').write_text('\n'.join(plan)+'\n')
    print(f'{len(SLIDES)} slides, {sum(minutes)} minutes; {len(content.encode())/1e6:.2f} MB')


if __name__=='__main__':main()
